import React, { useState } from "react";
import { useHistory } from "react-router-dom";
import "./adminPortfolio.css";
import Navbar from "../components/navbar";

<Navbar></Navbar>
const AdminPortfolio = () => {
  const history = useHistory();
  const [isSettingsMenuVisible, setIsSettingsMenuVisible] = useState(false);

  const handleSettingsClick = () => {
    setIsSettingsMenuVisible(!isSettingsMenuVisible);
  };

  const handleMenuOptionClick = (option) => {
    setIsSettingsMenuVisible(false);
    // Handle menu option click (e.g., navigate to another page or trigger a function)
    console.log(`${option} clicked`);
  };

  const handleConfirmClick = () => {
    // Add your confirmation logic here
    console.log("Confirm button clicked");
    alert("Confirm action performed.");
  };

  const handleOtpClick = () => {
    // Add your OTP logic here
    console.log("OTP button clicked");
    alert("OTP action performed.");
  };

  const handleEdit = (id) => {
    // Logic for editing item with the given id
    console.log(`Edit button clicked for item with ID: ${id}`);
  };

  const handleDelete = (id) => {
    // Logic for deleting item with the given id
    console.log(`Delete button clicked for item with ID: ${id}`);
    if (window.confirm("Are you sure you want to delete this item?")) {
      // Perform the delete operation
      console.log(`Item with ID: ${id} deleted.`);
    }
  };

  const handleView = (id) => {
    // Logic for viewing details of item with the given id
    console.log(`View button clicked for item with ID: ${id}`);
    // You can navigate to a detailed view or display more information
  };

  return (
    <div>
      {/* Header */}
      <header>
        <button id="back-button" onClick={() => history.goBack()}>Back</button>
        <h1>Admin Portfolio</h1>
        <button id="settings" onClick={handleSettingsClick}>
          Settings
          <span className="settings-menu-button">&#9662;</span> {/* Dropdown arrow */}
        </button>
        <div className={`settings-menu ${isSettingsMenuVisible ? "visible" : "hidden"}`}>
          <ul>
            <li><a href="#theme" onClick={() => handleMenuOptionClick("Theme")}>Theme</a></li>
            <li><a href="#signout" onClick={() => handleMenuOptionClick("Sign Out")}>Sign Out</a></li>
            <li><a href="#previous-orders" onClick={() => handleMenuOptionClick("Previous Orders")}>Previous Orders</a></li>
          </ul>
        </div>
      </header>

      {/* Main Content */}
      <main>
        <div className="table-container">
          {/* Users Table */}
          <section>
            <h2>List of Users</h2>
            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>User ID</th>
                    <th>Name</th>
                    <th>Project Description</th>
                    <th>Status</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td><a href="user1.html">1</a></td>
                    <td>John Doe</td>
                    <td>Project Alpha</td>
                    <td>Active</td>
                    <td>
                      <div className="action-buttons">
                        <button className="button edit-btn" onClick={() => handleEdit(1)}>Edit</button>
                        <button className="button delete-btn" onClick={() => handleDelete(1)}>Delete</button>
                        <button className="button view-btn" onClick={() => handleView(1)}>View</button>
                      </div>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </section>
        </div>

        <div className="table-container">
          {/* Builders Table */}
          <section>
            <h2>List of Builders</h2>
            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>Builder ID</th>
                    <th>Name</th>
                    <th>Sites</th>
                    <th>Status</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td><a href="builder1.html">1</a></td>
                    <td>Builder Inc.</td>
                    <td>Site A</td>
                    <td>Active</td>
                    <td>
                      <div className="action-buttons">
                        <button className="button edit-btn" onClick={() => handleEdit(1)}>Edit</button>
                        <button className="button delete-btn" onClick={() => handleDelete(1)}>Delete</button>
                        <button className="button view-btn" onClick={() => handleView(1)}>View</button>
                      </div>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </section>
        </div>

        {/* Footer Buttons */}
        <div className="footer-buttons">
          <button className="button confirm-btn" onClick={handleConfirmClick}>Confirm</button>
          <button className="button otp-btn" onClick={handleOtpClick}>OTP</button>
        </div>
      </main>
    </div>
  );
};

export default AdminPortfolio;
